mapper.update:
update classes
name = #{name}, content = #{content}, teacher_id = #{teacherId}, speciality_id = #{specialityId},
where id = #{id}

mapper.select:
select cl.*, t.name as teacherName from classes cl
                                            left join teacher t on cl.teacher_id = t.id
where cl.id = #{id}

select cl.*, t.name as teacherName
from classes cl
left join teacher t on cl.teacher_id = t.id

    and cl.id = #{id}
    and cl.name like concat('%', #{name}, '%')
    and cl.teacher_id = #{teacherId}
    and cl.speciality_id = #{specialityId}

order by cl.id desc
